"""GIS Copilot (Akinboyewa et al., arXiv 2411.03205): the 110 test cases of its Appendices 3–5
(60 basic, 30 intermediate, 20 advanced), summarised in our own words and mapped to LayeredMap.

The plugin code (github.com/GIS-Copilot/SpatialAnalysisAgent) is GPL-3.0 and the separate
test-case repository is empty, so only the paper's appendix tables were used, and no task text is
copied: summaries, requests and plans are ours. The tier is in each record's notes.

    python -I tools/lm/benchmarks/convert/gis_copilot.py   → sources/gis_copilot.jsonl
"""

from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))  # python -I drops the script's folder

from f4_common import call, case, cond, dist, obj, rec, refuse, sel, write  # noqa: E402

SRC = "GIS Copilot"
LIC = "arXiv paper (2411.03205) appendix tables; plugin code GPL-3.0; no separate test-data licence"
C = "copilot_us"
PA = cond("state", "is", "Pennsylvania")


def R(sid, tier, summary, category, coverage, **kw):
    notes = kw.pop("notes", "")
    kw["notes"] = f"tier: {tier}" + (f". {notes}" if notes else "")
    return rec(SRC, LIC, sid, summary, category, coverage, **kw)


def chart(sid, tier, n, summary, request, extra=""):
    return R(sid, tier, summary, "map_making", "out_of_scope", oos="code", confidence="medium",
             notes="VOCAB_GAP: chart. The deliverable is a chart or a plotting script, which LayeredMap has no action for" + extra,
             cases=[refuse(f"gcp-{n}", request, C)])


